/* Original vocabulary browsing and short dictation exercises. */
const VOCAB_STAGES={foundation:'基础恢复',bridge:'N3 衔接',n2:'N2 拓展'};
const vocabStage=v=>v.stage||v.level;
const stageTitle=v=>VOCAB_STAGES[vocabStage(v)]||'自添词';
const stageOptions=(selected,all=false)=>(all?'<option value="all">全部阶段</option>':'')+Object.entries(VOCAB_STAGES).map(([id,name])=>`<option value="${id}" ${id===selected?'selected':''}>${name}</option>`).join('');
const kanaKey=value=>String(value).normalize('NFKC').replace(/[\u30a1-\u30f6]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60)).replace(/[\s\u3000]/g,'').toLowerCase();
let libraryFilter={query:'',stage:'all',topic:'all',status:'all',theme:'all',referenceLevel:'all',page:0};
let wordDrill=null;
function vocabularyStagePicker(){return `<div class="filter-row"><label class="visually-hidden" for="vocab-stage">词汇学习阶段</label><select id="vocab-stage">${stageOptions(state.vocabStage)}</select><small>先补基础；切换阶段后，旧词仍按时复习。</small></div>`;}
function vocabularyDetail(v){return `${v.collocation?`<p class="collocation"><small>常用搭配</small><span class="jp" lang="ja">${esc(v.collocation)}</span></p>`:''}${v.example?`<p class="example jp" lang="ja">${esc(v.example)}</p><p class="translation">${esc(v.exampleZh)}</p>`:''}${v.note?`<p class="usage-note">${esc(v.note)}</p>`:''}${v.dictionarySenses?`<div class="dictionary-senses"><h4>中文词典义项</h4><ol>${v.dictionarySenses.map(s=>`<li>${esc(s.glosses.join('；'))}${s.notes?`<small>${esc(s.notes)}</small>`:''}</li>`).join('')}</ol><p class="panel-note">词表参考英义：${esc(v.referenceMeaning)}。不同义项请结合上下文区分。</p><p class="panel-note">释义来源：Tomoshi / JMdict；人工补写的未匹配词另行标注。${v.manualGloss?'此条中文为本站补写。':''}</p></div>`:''}`;}

function vocabularyOverview(){return `<section class="card vocabulary-overview"><div class="card-head"><h2>词库，慢慢走完</h2><small>${DATA.vocabulary.length} 个词条</small></div><div class="stage-progress">${Object.entries(VOCAB_STAGES).map(([id,name])=>{const words=DATA.vocabulary.filter(v=>vocabStage(v)===id),touched=words.filter(v=>state.reviews[v.id]).length;return `<div><div><span>${name}</span><small>${touched} / ${words.length} 已接触</small></div><progress value="${touched}" max="${words.length||1}" aria-label="${name}词汇进度"></progress></div>`;}).join('')}</div><div class="button-row section-gap"><button class="button secondary" data-action="word-audio-library">查词与词库总览 ↗</button><button class="button ghost" data-action="word-drill-start">▷ 听音写假名 · 5 词</button></div><p class="panel-note">每天最多 5 个新词，先完成到期复习。词条分层用于安排学习。可在词库中把不熟的词设为「优先学习」，每日新词上限不变。</p>${textbookThemesPanel()}${vocabularyDatasetCredit()}</section>`;}
function libraryMatches(filter=libraryFilter){const query=kanaKey(filter.query);return vocab().filter(v=>(filter.stage==='all'||vocabStage(v)===filter.stage)&&(filter.topic==='all'||(v.topic||'自添词句')===filter.topic)&&(!filter.theme||filter.theme==='all'||v.themes?.includes(filter.theme))&&(!filter.referenceLevel||filter.referenceLevel==='all'||v.referenceLevel===filter.referenceLevel)&&(filter.status==='all'||(filter.status==='audio'&&(bundledWordRecording(v)||hasWordRecording(v.id)))||(filter.status==='due'&&state.reviews[v.id]?.due<=today)||(filter.status==='new'&&!state.reviews[v.id]))&&(!query||kanaKey([v.word,v.reading,v.meaning,v.collocation,v.example,v.topic].filter(Boolean).join(' ')).includes(query)));}
function openVocabularyLibrary(){stopWordAudio();libraryFilter={query:'',stage:'all',topic:'all',status:'all',theme:'all',referenceLevel:'all',page:0};const topics=[...new Set(vocab().map(v=>v.topic||'自添词句'))].sort((a,b)=>a.localeCompare(b,'zh-CN'));modal('词库总览',`<p class="subtext">搜索日语、假名、中文或搭配。这里可随时查阅，不改变每日新词额度。</p><div class="library-filters"><label class="library-search">搜索词库<input id="vocab-query" type="search" maxlength="120" placeholder="例如：とどく、借、自动词" autocomplete="off"></label><label>阶段<select id="library-stage">${stageOptions('all',true)}</select></label><label>主题<select id="library-topic"><option value="all">全部主题</option>${topics.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select></label><label>教材主题<select id="library-theme"><option value="all">全部主题</option>${(DATA.vocabularyMeta?.themes||[]).map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><label>词表参考分级<select id="library-reference"><option value="all">全部参考级别</option>${['N5','N4','N3','N2'].map(l=>`<option value="${l}">${l}</option>`).join('')}</select></label><label>学习情况<select id="library-status"><option value="all">全部词条</option><option value="due">今天到期</option><option value="new">尚未学习</option><option value="audio">已有词条录音</option></select></label></div><div id="vocab-results" aria-live="polite"></div>`);updateVocabularyResults();}
function updateVocabularyResults(){const matches=libraryMatches(),pageSize=20,pages=Math.max(1,Math.ceil(matches.length/pageSize));libraryFilter.page=Math.max(0,Math.min(libraryFilter.page,pages-1));const rows=matches.slice(libraryFilter.page*pageSize,(libraryFilter.page+1)*pageSize);$('#vocab-results').innerHTML=`<p class="panel-note">找到 ${matches.length} 个词 · 第 ${libraryFilter.page+1} / ${pages} 页</p>${rows.length?rows.map(v=>`<article class="library-entry"><div class="library-word"><div><strong class="jp" lang="ja">${esc(v.word)}</strong><span class="reading jp" lang="ja">${esc(v.reading)}</span></div><button class="button ghost" data-action="speak-word" data-id="${esc(v.id)}" aria-label="播放${esc(v.word)}的读音">${wordAudioButtonLabel(v)}</button></div><p class="library-meaning">${esc(v.meaning)}</p><div class="library-tags"><span class="pill">${stageTitle(v)}</span><small>${esc(v.topic||'自添词句')}</small><small>${state.reviews[v.id]?(state.reviews[v.id].due<=today?'今天到期':'下次 '+state.reviews[v.id].due):'尚未学习'}</small></div><div class="button-row section-gap"><button class="button secondary" data-action="prioritize-word" data-id="${esc(v.id)}" ${state.reviews[v.id]||state.priorityWords.includes(v.id)?'disabled':''}>${state.reviews[v.id]?'已在复习队列':state.priorityWords.includes(v.id)?'已设为优先新词':'＋ 优先学习这个词'}</button>${v.referenceLevel?`<span class="pill">词表参考 ${esc(v.referenceLevel)}</span>`:''}</div><details><summary>${v.example?'搭配与例句':'词义与来源'}</summary>${vocabularyDetail(v)}${wordVoiceLinks(v)}</details></article>`).join(''):'<p class="empty">没有找到匹配词条。试试更短的词或切换筛选。</p>'}<div class="library-pagination"><button class="button ghost" data-action="library-prev" ${libraryFilter.page===0?'disabled':''}>上一页</button><span>${libraryFilter.page+1} / ${pages}</span><button class="button ghost" data-action="library-next" ${libraryFilter.page===pages-1?'disabled':''}>下一页</button></div>${wordAudioCredit()}`;}
function drillCandidates(){const last=new Map();state.wordPractice.forEach((r,i)=>last.set(r.id,{...r,index:i}));return vocab().filter(v=>vocabStage(v)===state.vocabStage&&/^[ぁ-ゖー]+$/u.test(kanaKey(v.reading))&&(bundledWordRecording(v)||hasWordRecording(v.id))).sort((a,b)=>{const score=v=>{const r=last.get(v.id);return r&&!r.correct?-3000+r.index:!r?(state.reviews[v.id]?-2000:-1000):r.index;};return score(a)-score(b);}).slice(0,5);}
function startWordDrill(){stopWordAudio();const words=drillCandidates();wordDrill={ids:words.map(v=>v.id),index:0,answers:[],checked:false,input:''};renderWordDrill();}
function renderWordDrill(){if(!wordDrill)return;const v=vocab().find(w=>w.id===wordDrill.ids[wordDrill.index]);if(!v){const correct=wordDrill.answers.filter(a=>a.correct).length;modal('听音小练习',wordDrill.ids.length?`<div class="drill-finish"><span class="eyebrow">本轮听写</span><h3>${correct} / ${wordDrill.answers.length}</h3><p class="subtext">${correct===wordDrill.answers.length?'这些词的声音更熟悉了。':'没听清的词已存入积累手账，下轮优先再练。'}<br>听写单独记录；词卡复习进度由你翻卡后判断。</p></div><div class="button-row"><button class="button" data-action="word-drill-start">再练 5 词</button><button class="button ghost" data-action="close-modal">回到学习</button></div>`:'<p class="subtext">当前阶段还没有同时具备假名读音和录音的词。可切换阶段，或为自添词补齐读音与音频。</p>');return;}const result=wordDrill.answers[wordDrill.index];modal('听音写假名',`<div class="status-row"><span>${stageTitle(v)}</span><span>${wordDrill.index+1} / ${wordDrill.ids.length}</span></div><div class="dictation-prompt"><span class="sound-symbol" aria-hidden="true">♪</span><h3>先让耳朵认出这个词。</h3><button class="button" data-action="drill-play">▷ ${hasWordRecording(v.id)?'播放导入音频':'播放真人读音'}</button><p class="panel-note">可重复播放；使用日语键盘输入假名，注意长音与促音。</p></div>${!wordDrill.checked?`<form id="word-drill-form"><label for="drill-answer" class="subtext">你听到的读音</label><input id="drill-answer" name="answer" lang="ja" maxlength="150" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="输入平假名或片假名"><div class="button-row section-gap"><button class="button" type="submit">核对读音</button><button class="button ghost" type="button" data-action="drill-skip">还没听清 · 看答案</button></div></form>`:`<div class="feedback ${result.correct?'':'wrong'}"><strong>${result.correct?'读音写对了。':'对照读音，再听一遍。'}</strong><p class="subtext">你的输入：${esc(result.input||'尚未填写')}</p><h3 class="jp" lang="ja">${esc(v.word)} · ${esc(v.reading)}</h3><p>${esc(v.meaning)}</p>${vocabularyDetail(v)}</div><button class="button section-gap" data-action="drill-next">${wordDrill.index+1===wordDrill.ids.length?'查看本轮结果':'下一个词 →'}</button>`}`);}
function checkWordDrill(input,skip=false){if(!wordDrill||wordDrill.checked)return;if(dayKey()!==today)render();const v=vocab().find(w=>w.id===wordDrill.ids[wordDrill.index]);if(!v)return;input=String(input||'').trim().slice(0,150);if(!input&&!skip){toast('先输入听到的假名，或选择「还没听清」。');return;}const correct=!skip&&kanaKey(input)===kanaKey(v.reading);wordDrill.checked=true;wordDrill.answers.push({id:v.id,input,correct});state.wordPractice.push({id:v.id,date:today,correct});state.wordPractice=state.wordPractice.slice(-1000);if(!correct)addNote('word-listen-'+v.id,'听音易混：'+v.word,'正确读音：'+v.reading+'\n我的输入：'+(input||'没听清')+'\n'+v.meaning+'\n搭配：'+(v.collocation||v.example),'听写');persist();renderWordDrill();}
document.addEventListener('input',e=>{if(e.target.id==='vocab-query'){libraryFilter.query=e.target.value;libraryFilter.page=0;updateVocabularyResults();}});
document.addEventListener('change',e=>{const filters={'library-stage':'stage','library-topic':'topic','library-status':'status','library-theme':'theme','library-reference':'referenceLevel'};if(filters[e.target.id]){libraryFilter[filters[e.target.id]]=e.target.value;libraryFilter.page=0;updateVocabularyResults();}if(e.target.id==='vocab-stage'&&Object.hasOwn(VOCAB_STAGES,e.target.value)){stopWordAudio();state.vocabStage=e.target.value;queueActive=false;persist();render();}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='word-drill-start')startWordDrill();if(action==='drill-play'&&wordDrill){const v=vocab().find(w=>w.id===wordDrill.ids[wordDrill.index]);if(v)playWordAudio(v,{requireRecording:true});}if(action==='drill-skip')checkWordDrill('',true);if(action==='drill-next'&&wordDrill?.checked){stopWordAudio();wordDrill.index++;wordDrill.checked=false;renderWordDrill();}if(action==='library-prev'||action==='library-next'){stopWordAudio();libraryFilter.page+=action==='library-next'?1:-1;updateVocabularyResults();$('#vocab-results').scrollIntoView?.({block:'start',behavior:'smooth'});}});
document.addEventListener('submit',e=>{if(e.target.id!=='word-drill-form')return;e.preventDefault();const data=new FormData(e.target);checkWordDrill(Object.fromEntries(data).answer);});

function githubLearningReferences(){const projects=[
 ['Qwerty Learner','https://github.com/RealKai42/qwerty-learner','GPL-3.0 · 交互参考','借鉴短练习与即时反馈，加入双向词卡、键盘快捷键和听写错词重练。'],
 ['Lute v3','https://github.com/LuteOrg/lute-v3','MIT · 交互参考','借鉴阅读中的词汇积累，为短文提供重点词查阅与优先学习入口。'],
 ['Kakugo','https://github.com/blastrock/kakugo','GPL-3.0-or-later · 交互参考','借鉴可中断的小步练习，保留课堂进度并显示词汇复习预览。'],
 ['asbplayer','https://github.com/asbplayer/asbplayer','AGPL-3.0-or-later，部分 MIT · 交互参考','借鉴先听再看文本的流程，为原创微课加入对话听题和单句合成语音跟读。'],
 ['Tofugu / WaniKani','https://github.com/tofugu/japanese-vocabulary-pronunciation-audio','录音 CC BY-SA 4.0','选取词形与读音匹配的真人词音，已内置离线播放。'],
 ['Kanji alive','https://github.com/kanjialive/kanji-data-media','数据与音频 CC BY 4.0','提供本站「取り組む」的真人词音。']
 ];return `<section class="card"><div class="card-head"><h2>GitHub 上的学习工具参考</h2><small>2026-10-14 核查</small></div><p class="subtext">学习界面、课堂和练习逻辑由本站独立编写，未引入这些应用的源代码。现有词库与录音保留各自的来源和许可。</p><div class="grammar-grid">${projects.map(([name,url,license,description])=>`<div class="resource"><a href="${url}" target="_blank" rel="noopener"><strong>${name} ↗</strong></a><p>${description}</p><small>${license}</small></div>`).join('')}</div></section>`;}

function vocabularyDatasetCredit(){const m=DATA.vocabularyMeta;if(!m)return '';return `<p class="panel-note">覆盖所选开放词表的 N5—N2 共 ${m.sourceCount.toLocaleString()} 条，另保留补充词；其中320张详解卡有本站搭配与原创例句，新增词条提供分义项中文词典释义。社区分级不是官方完整考纲。</p><details class="vocabulary-source"><summary>词库来源与更新日期 · ${m.checkedAt}</summary><p class="panel-note">词表：<a href="https://github.com/evanclan/OpenJLPT" target="_blank" rel="noopener">OpenJLPT</a> / <a href="https://www.tanos.co.uk/jlpt/" target="_blank" rel="noopener">Jonathan Waller</a>；词典：<a href="https://www.edrdg.org/jmdict/j_jmdict.html" target="_blank" rel="noopener">JMdict © EDRDG</a>；中文译释：<a href="https://github.com/tomoshi-app/tomoshi-dict-data" target="_blank" rel="noopener">Tomoshi © Y1Z</a>，含机器辅助翻译与复核。词库派生数据以 <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a> 提供，已作选词、义项关联、主题分类与少量纠错；有疑义请对照上下文核实。</p></details>`;}
function textbookThemesPanel(){const themes=DATA.vocabularyMeta?.themes||[];if(!themes.length)return '';return `<details class="textbook-themes"><summary>按教材主题查缺补漏</summary><p class="panel-note">参考《标准日本语》初中级与《新时代大学日语》公开教学主题，独立组织词群。这里不是两套教材逐课生词表。</p><div class="theme-buttons">${themes.map(t=>`<button class="button ghost" data-action="textbook-topic" data-id="${t.id}">${esc(t.title)}<small>${t.count} 词</small></button>`).join('')}</div><p class="panel-note"><a href="https://www.mitsumura-tosho.co.jp/shoseki/nihongo/c" target="_blank" rel="noopener">标日中级 · 官方介绍 ↗</a> · <a href="https://welearn.sflep.com/course/courseinfo.aspx?cid=2721" target="_blank" rel="noopener">新时代第3册 · 官方目录 ↗</a> · <a href="https://we.sflep.com/Course/CourseDetail.aspx?cid=2722" target="_blank" rel="noopener">第4册目录 ↗</a></p></details>`;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='textbook-topic'){openVocabularyLibrary();libraryFilter.theme=el.dataset.id;$('#library-theme').value=el.dataset.id;updateVocabularyResults();}if(el.dataset.action==='prioritize-word'){const id=el.dataset.id;if(!vocab().some(v=>v.id===id)||state.reviews[id]||state.priorityWords.includes(id))return;state.priorityWords.push(id);queueActive=false;persist();render();updateVocabularyResults();toast('已加入优先新词；到期词仍在前，每天最多5个新词。');}});
